(37, '上海', '在上海租房，也要好好生活', 5, 6, 0, '1991-02-11', 339, 3, '2026-09-01 10:00:00', '2026-10-01 10:00:00'),
(38, '上海', '周末喜欢约朋友来家里', 2, 2, 1, '1992-03-12', 346, 4, '2026-09-01 10:00:00', '2026-10-01 10:00:00'),
(39, '上海', '对服务体验有点挑剔', 2, 9, 0, '1993-04-13', 353, 5, '2026-09-01 10:00:00', '2026-10-01 10:00:00'),
(40, '上海', '爱下厨的产品经理，家宴爱好者', 6, 5, 1, '1994-05-14', 360, 1, '2026-09-01 10:00:00', '2026-10-01 10:00:00');
INSERT INTO `t_note` (`id`, `provider_id`, `user_id`, `title`, `images`, `content`, `liked`, `comments`, `create_time`, `update_time`) VALUES
(1, 1, 4, '第一次请私厨，比想象中省心', '/imgs/notes/1/2/4a7b496b-2a08-4af7-aa95-df2c3bd0ef97.jpg,/imgs/notes/1/2/f052df92-fc05-41a6-866e-d6da63b27645.jpg,/imgs/notes/10/7/7e97f47d-eb49-4dc9-a583-95faa7aed287.jpg', '本来担心陌生人在家做饭会尴尬，结果师傅进门先换鞋、戴口罩，做完还把垃圾带走。菜是现买的，虾还在动，味道比我妈做的还正。', 71, 13, '2026-09-03 17:00:00', '2026-09-03 17:00:00'),
(2, 2, 7, '八菜一汤的家宴，亲戚都问在哪订的', '/imgs/notes/11/12/8b37d208-9414-4e78-b065-9199647bb3e3.jpg,/imgs/notes/11/4/fbfe0547-bd5d-454c-98c4-411e2e0dce65.jpg,/imgs/notes/11/8/ca9ba6e6-068a-4a09-8b12-5719f86d270c.jpg', '十个人吃得刚刚好，剩了一点打包。最惊喜的是摆盘，普通家常菜摆得像餐厅出品，长辈拍照发了一整晚朋友圈。', 124, 11, '2026-09-05 22:00:00', '2026-09-05 22:00:00'),
(3, 2, 8, '一人食周餐，解救加班党', '/imgs/notes/11/4/fbfe0547-bd5d-454c-98c4-411e2e0dce65.jpg,/imgs/notes/11/8/ca9ba6e6-068a-4a09-8b12-5719f86d270c.jpg', '连续订了三周，每天晚上七点准时送到，荤素搭配不重样，比外卖健康太多。有一次加班到十点，师傅还帮我热了一下。', 155, 9, '2026-09-10 13:00:00', '2026-09-10 13:00:00'),
(4, 3, 10, '一人食周餐，解救加班党', '/imgs/notes/12/1/1afd01e5-0e16-43c2-b655-4bf733f95cfc.jpg,/imgs/notes/12/9/aab78497-ec7a-46da-820a-0ee0bbe103a3.jpg', '连续订了三周，每天晚上七点准时送到，荤素搭配不重样，比外卖健康太多。有一次加班到十点，师傅还帮我热了一下。', 177, 7, '2026-09-07 15:00:00', '2026-09-07 15:00:00'),
(5, 4, 13, '本帮菜做得地道，红烧肉入口即化', '/imgs/notes/13/4/1bb3d189-a34a-4809-b062-323cda7d19a9.jpg,/imgs/notes/14/13/2ec4622e-de82-4bb3-9acf-33b589850cd2.jpg,/imgs/notes/14/13/31bc9613-3637-4a36-9082-e37ce0909cbd.jpg', '浓油赤酱但是不齁，甜度是上海人喜欢的那个度。厨房收拾得干干净净，油烟机都擦了。', 230, 14, '2026-09-09 20:00:00', '2026-09-09 20:00:00'),
(6, 4, 14, '深夜加餐也能约到，太适合聚会了', '/imgs/notes/14/13/2ec4622e-de82-4bb3-9acf-33b589850cd2.jpg,/imgs/notes/14/13/31bc9613-3637-4a36-9082-e37ce0909cbd.jpg,/imgs/notes/14/3/52b290eb-8b5d-403b-8373-ba0bb856d18e.jpg', '朋友临时来家里，晚上九点下单，十点半师傅就到了，半小时出四个菜，救场神器。', 261, 12, '2026-09-14 23:00:00', '2026-09-14 23:00:00'),
(7, 5, 16, '深夜加餐也能约到，太适合聚会了', '/imgs/notes/14/3/52b290eb-8b5d-403b-8373-ba0bb856d18e.jpg,/imgs/notes/15/0/b61bf453-28fc-4824-84c8-783803464c4f.jpg,/imgs/notes/15/3/fd5802b1-d4a5-4e45-badd-05cbc46c8c3d.jpg', '朋友临时来家里，晚上九点下单，十点半师傅就到了，半小时出四个菜，救场神器。', 283, 10, '2026-09-11 13:00:00', '2026-09-11 13:00:00'),
(8, 6, 19, '请主厨上门做生日宴，爸妈直呼太值了', '/imgs/notes/15/9/cea51d9b-ac15-49f6-b9f1-9cf81e9b9c85.jpg,/imgs/notes/2/1/7b31a5da-4ee3-4c9e-a38a-2dbc8de0345a.jpg', '给爸妈结婚纪念日订了一次上门私宴，主厨提前两天沟通菜单，当天自带厨具，四菜一汤全程在家看着做，最后厨房收拾得比来之前还干净。人均不到一百二，比在外面包间划算太多了。', 56, 8, '2026-09-13 18:00:00', '2026-09-13 18:00:00'),
(9, 6, 20, '第一次请私厨，比想象中省心', '/imgs/notes/2/1/7b31a5da-4ee3-4c9e-a38a-2dbc8de0345a.jpg,/imgs/notes/2/2/852f49b7-432c-4d01-b7b1-8e152854f2a9.jpg,/imgs/notes/2/3/39d65be4-af94-458d-b6de-bc8ca20735bb.jpg', '本来担心陌生人在家做饭会尴尬，结果师傅进门先换鞋、戴口罩，做完还把垃圾带走。菜是现买的，虾还在动，味道比我妈做的还正。', 87, 6, '2026-09-18 21:00:00', '2026-09-18 21:00:00'),
(10, 7, 22, '无酒精版本也做得很好喝', '/imgs/notes/2/3/39d65be4-af94-458d-b6de-bc8ca20735bb.jpg,/imgs/notes/2/4/7ed91c85-975a-40dd-9f36-abb2e87a1155.jpg,/imgs/notes/2/6/b0756279-65da-4f2d-b62a-33f74b06454a.jpg', '家里有孕妇，本来担心只有我一个人喝没气氛，结果调酒师做了三款 0 度的，颜值和口感都在线，小朋友也抢着喝。', 109, 13, '2026-09-15 23:00:00', '2026-09-15 23:00:00'),
(11, 8, 25, '公司团建请到家里，气氛直接拉满', '/imgs/notes/3/12/9b19dd28-1eb1-4b70-bdc2-95544eecfeb2.jpg,/imgs/notes/3/14/a6b9ec21-6708-4d6d-8f77-ed31c856e5b2.jpg,/imgs/notes/3/15/af0db3fa-5cf9-4eeb-a9fe-938de64bddc6.jpg', '十二个人，两位调酒师全程没停手，结束还把吧台擦干净了。老板当场问我要了联系方式。', 162, 11, '2026-09-17 16:00:00', '2026-09-17 16:00:00'),
(12, 8, 26, '第一次知道冰块也分这么多种', '/imgs/notes/3/14/a6b9ec21-6708-4d6d-8f77-ed31c856e5b2.jpg,/imgs/notes/3/15/af0db3fa-5cf9-4eeb-a9fe-938de64bddc6.jpg', '老冰、球冰、碎冰各有各的用法，光是看他凿冰就很解压。酒单会提前发过来让我们选。', 193, 9, '2026-09-22 19:00:00', '2026-09-22 19:00:00'),
(13, 9, 28, '第一次知道冰块也分这么多种', '/imgs/notes/4/0/26a7cd7e-6320-432c-a0b4-1b7418f45ec7.jpg,/imgs/notes/4/1/fa74a6d6-3026-4cb7-b0b6-35abb1e52d11.jpg', '老冰、球冰、碎冰各有各的用法，光是看他凿冰就很解压。酒单会提前发过来让我们选。', 215, 7, '2026-09-19 21:00:00', '2026-09-19 21:00:00'),
(14, 10, 31, '老上海风格，拍照特别出片', '/imgs/notes/6/0/081b4b46-b2c0-47b1-8e2a-8f620d0307fb.jpg,/imgs/notes/6/8/5593ee62-04e1-410a-b6a7-4c1d50d2aee2.jpg,/imgs/notes/7/1/6f4c2442-1d3b-436f-8d49-cc704f9f0bf8.jpg', '调酒师穿了复古马甲，带了黄铜器具，客厅灯光一打，随手拍都像电影。', 268, 14, '2026-09-21 14:00:00', '2026-09-21 14:00:00'),
(15, 10, 32, '品鉴课比自己瞎喝强太多', '/imgs/notes/6/8/5593ee62-04e1-410a-b6a7-4c1d50d2aee2.jpg,/imgs/notes/7/1/6f4c2442-1d3b-436f-8d49-cc704f9f0bf8.jpg,/imgs/notes/7/3/2f6769c9-21de-42f8-adc0-77873273997f.jpg', '90 分钟讲了三款基酒的区别，还教了怎么闻香。回家自己调了一杯，居然没翻车。', 19, 12, '2026-09-26 17:00:00', '2026-09-26 17:00:00'),
(16, 11, 34, '品鉴课比自己瞎喝强太多', '/imgs/notes/7/3/2f6769c9-21de-42f8-adc0-77873273997f.jpg,/imgs/notes/blog1.jpg,/imgs/notes/0/0/feb2a83e-5646-46c0-a982-5e43fed31b22.jpg', '90 分钟讲了三款基酒的区别，还教了怎么闻香。回家自己调了一杯，居然没翻车。', 41, 10, '2026-09-23 19:00:00', '2026-09-23 19:00:00'),
(17, 12, 37, '闺蜜生日会，特调师把客厅变成小酒吧', '/imgs/notes/0/5/e3e7c9e7-6654-4065-b47a-b86eb4541c33.jpg,/imgs/notes/1/12/ab329e30-b4e1-446e-993b-b00be783f142.jpg', '六个姑娘一人两杯，调酒师会按口味改配方，微醺刚好。器具带得超全，结束后还教我们两招，下次聚会自己也能糊弄一下。', 94, 8, '2026-09-25 12:00:00', '2026-09-25 12:00:00'),
(18, 12, 38, '无酒精版本也做得很好喝', '/imgs/notes/1/12/ab329e30-b4e1-446e-993b-b00be783f142.jpg,/imgs/notes/1/2/38f7e67d-7b26-41fd-bcf5-eebf71914230.jpg,/imgs/notes/1/2/4a7b496b-2a08-4af7-aa95-df2c3bd0ef97.jpg', '家里有孕妇，本来担心只有我一个人喝没气氛，结果调酒师做了三款 0 度的，颜值和口感都在线，小朋友也抢着喝。', 125, 6, '2026-09-30 15:00:00', '2026-09-30 15:00:00'),
(19, 13, 40, '求婚布置帮我省了半个策划师', '/imgs/notes/1/2/4a7b496b-2a08-4af7-aa95-df2c3bd0ef97.jpg,/imgs/notes/1/2/f052df92-fc05-41a6-866e-d6da63b27645.jpg,/imgs/notes/10/7/7e97f47d-eb49-4dc9-a583-95faa7aed287.jpg', '我只说了句「想要温柔一点」，方案直接给了三版。当天提前两小时到场，我到家的时候灯已经亮了，女朋友当场哭了。', 147, 13, '2026-09-27 17:00:00', '2026-09-27 17:00:00'),
(20, 14, 3, '小朋友的生日会，同学家长都在问', '/imgs/notes/11/12/8b37d208-9414-4e78-b065-9199647bb3e3.jpg,/imgs/notes/11/4/fbfe0547-bd5d-454c-98c4-411e2e0dce65.jpg,/imgs/notes/11/8/ca9ba6e6-068a-4a09-8b12-5719f86d270c.jpg', '主题是太空，背景板、气球、桌旗统一配色，连蛋糕托都配好了。两个小时布置完，孩子们玩疯了。', 200, 11, '2026-09-29 22:00:00', '2026-09-29 22:00:00'),
(21, 14, 4, '中式抓周很有仪式感', '/imgs/notes/11/4/fbfe0547-bd5d-454c-98c4-411e2e0dce65.jpg,/imgs/notes/11/8/ca9ba6e6-068a-4a09-8b12-5719f86d270c.jpg', '红金配色不俗气，抓周道具很精致，爷爷奶奶特别满意。', 231, 9, '2026-10-04 13:00:00', '2026-10-04 13:00:00'),
(22, 15, 6, '中式抓周很有仪式感', '/imgs/notes/12/1/1afd01e5-0e16-43c2-b655-4bf733f95cfc.jpg,/imgs/notes/12/9/aab78497-ec7a-46da-820a-0ee0bbe103a3.jpg', '红金配色不俗气，抓周道具很精致，爷爷奶奶特别满意。', 253, 7, '2026-10-01 15:00:00', '2026-10-01 15:00:00'),
(23, 16, 9, '预算内做到了想要的效果', '/imgs/notes/13/4/1bb3d189-a34a-4809-b062-323cda7d19a9.jpg,/imgs/notes/14/13/2ec4622e-de82-4bb3-9acf-33b589850cd2.jpg,/imgs/notes/14/13/31bc9613-3637-4a36-9082-e37ce0909cbd.jpg', '预算三千，方案里该省的省该花的花，最后效果比同事花五千的还好。', 26, 14, '2026-10-03 20:00:00', '2026-10-03 20:00:00'),
(24, 16, 10, '沟通很顺畅，改了三版方案也没不耐烦', '/imgs/notes/14/13/2ec4622e-de82-4bb3-9acf-33b589850cd2.jpg,/imgs/notes/14/13/31bc9613-3637-4a36-9082-e37ce0909cbd.jpg,/imgs/notes/14/3/52b290eb-8b5d-403b-8373-ba0bb856d18e.jpg', '我比较纠结配色，来回改了三版，策划师一直很耐心，还主动提醒我避开小区物业的时间限制。', 57, 12, '2026-10-08 23:00:00', '2026-10-08 23:00:00'),
(25, 17, 12, '沟通很顺畅，改了三版方案也没不耐烦', '/imgs/notes/14/3/52b290eb-8b5d-403b-8373-ba0bb856d18e.jpg,/imgs/notes/15/0/b61bf453-28fc-4824-84c8-783803464c4f.jpg,/imgs/notes/15/3/fd5802b1-d4a5-4e45-badd-05cbc46c8c3d.jpg', '我比较纠结配色，来回改了三版，策划师一直很耐心，还主动提醒我避开小区物业的时间限制。', 79, 10, '2026-10-05 13:00:00', '2026-10-05 13:00:00'),
(26, 18, 15, '宝宝周岁宴布置，氛围感直接拉满', '/imgs/notes/15/9/cea51d9b-ac15-49f6-b9f1-9cf81e9b9c85.jpg,/imgs/notes/2/1/7b31a5da-4ee3-4c9e-a38a-2dbc8de0345a.jpg', '气球拱门加背景墙，配色是我选的奶油色系，两位师傅三个小时搞定，还贴心地把尖锐处都包了防撞条。拆场第二天来收，完全不用操心。', 132, 8, '2026-10-07 18:00:00', '2026-10-07 18:00:00'),
(27, 18, 16, '求婚布置帮我省了半个策划师', '/imgs/notes/2/1/7b31a5da-4ee3-4c9e-a38a-2dbc8de0345a.jpg,/imgs/notes/2/2/852f49b7-432c-4d01-b7b1-8e152854f2a9.jpg,/imgs/notes/2/3/39d65be4-af94-458d-b6de-bc8ca20735bb.jpg', '我只说了句「想要温柔一点」，方案直接给了三版。当天提前两小时到场，我到家的时候灯已经亮了，女朋友当场哭了。', 163, 6, '2026-10-12 21:00:00', '2026-10-12 21:00:00'),
(28, 19, 18, '桌游管家太值了，规则不用自己啃', '/imgs/notes/2/3/39d65be4-af94-458d-b6de-bc8ca20735bb.jpg,/imgs/notes/2/4/7ed91c85-975a-40dd-9f36-abb2e87a1155.jpg,/imgs/notes/2/6/b0756279-65da-4f2d-b62a-33f74b06454a.jpg', '二十款桌游随便挑，管家讲规则讲得比说明书清楚，四个小时一点都不闷。', 185, 13, '2026-10-09 23:00:00', '2026-10-09 23:00:00'),
(29, 20, 21, '团建放在家里，比去密室划算', '/imgs/notes/3/12/9b19dd28-1eb1-4b70-bdc2-95544eecfeb2.jpg,/imgs/notes/3/14/a6b9ec21-6708-4d6d-8f77-ed31c856e5b2.jpg,/imgs/notes/3/15/af0db3fa-5cf9-4eeb-a9fe-938de64bddc6.jpg', '十五个人，人均不到一百，闯关设计得很用心，最后还有小奖品。', 238, 11, '2026-10-11 16:00:00', '2026-10-11 16:00:00'),
(30, 20, 22, '观影夜布置得很有氛围', '/imgs/notes/3/14/a6b9ec21-6708-4d6d-8f77-ed31c856e5b2.jpg,/imgs/notes/3/15/af0db3fa-5cf9-4eeb-a9fe-938de64bddc6.jpg', '灯串、抱枕、零食台都配齐了，投影调试也帮忙做了，看恐怖片效果拉满。', 269, 9, '2026-10-16 19:00:00', '2026-10-16 19:00:00'),
(31, 21, 24, '观影夜布置得很有氛围', '/imgs/notes/4/0/26a7cd7e-6320-432c-a0b4-1b7418f45ec7.jpg,/imgs/notes/4/1/fa74a6d6-3026-4cb7-b0b6-35abb1e52d11.jpg', '灯串、抱枕、零食台都配齐了，投影调试也帮忙做了，看恐怖片效果拉满。', 291, 7, '2026-10-13 21:00:00', '2026-10-13 21:00:00'),
(32, 22, 27, '管家会看眼色，不尴尬', '/imgs/notes/6/0/081b4b46-b2c0-47b1-8e2a-8f620d0307fb.jpg,/imgs/notes/6/8/5593ee62-04e1-410a-b6a7-4c1d50d2aee2.jpg,/imgs/notes/7/1/6f4c2442-1d3b-436f-8d49-cc704f9f0bf8.jpg', '该出现的时候出现，该消失的时候消失，不会一直站着让人有压力。', 64, 14, '2026-10-15 14:00:00', '2026-10-15 14:00:00'),
(33, 22, 28, '朋友聚会再也不用我操心流程', '/imgs/notes/6/8/5593ee62-04e1-410a-b6a7-4c1d50d2aee2.jpg,/imgs/notes/7/1/6f4c2442-1d3b-436f-8d49-cc704f9f0bf8.jpg,/imgs/notes/7/3/2f6769c9-21de-42f8-adc0-77873273997f.jpg', '以前每次聚会都是我张罗，这次终于能当个客人了。', 95, 12, '2026-10-20 17:00:00', '2026-10-20 17:00:00'),
(34, 23, 30, '朋友聚会再也不用我操心流程', '/imgs/notes/7/3/2f6769c9-21de-42f8-adc0-77873273997f.jpg,/imgs/notes/blog1.jpg,/imgs/notes/0/0/feb2a83e-5646-46c0-a982-5e43fed31b22.jpg', '以前每次聚会都是我张罗，这次终于能当个客人了。', 117, 10, '2026-10-17 19:00:00', '2026-10-17 19:00:00'),
(35, 24, 33, '生日轰趴请了管家，我全程只负责玩', '/imgs/notes/0/5/e3e7c9e7-6654-4065-b47a-b86eb4541c33.jpg,/imgs/notes/1/12/ab329e30-b4e1-446e-993b-b00be783f142.jpg', '从进门换鞋到切蛋糕，流程都有人盯。游戏环节没人冷场，连我那个不爱说话的表弟都玩嗨了。', 170, 8, '2026-10-19 12:00:00', '2026-10-19 12:00:00'),
(36, 24, 34, '桌游管家太值了，规则不用自己啃', '/imgs/notes/1/12/ab329e30-b4e1-446e-993b-b00be783f142.jpg,/imgs/notes/1/2/38f7e67d-7b26-41fd-bcf5-eebf71914230.jpg,/imgs/notes/1/2/4a7b496b-2a08-4af7-aa95-df2c3bd0ef97.jpg', '二十款桌游随便挑，管家讲规则讲得比说明书清楚，四个小时一点都不闷。', 201, 6, '2026-10-24 15:00:00', '2026-10-24 15:00:00'),
(37, 25, 36, '正骨那一下，我听到了咔的一声', '/imgs/notes/1/2/4a7b496b-2a08-4af7-aa95-df2c3bd0ef97.jpg,/imgs/notes/1/2/f052df92-fc05-41a6-866e-d6da63b27645.jpg,/imgs/notes/10/7/7e97f47d-eb49-4dc9-a583-95faa7aed287.jpg', '有点紧张但确实舒服，做完腰不酸了。师傅说不要天天做，一周一次就够。', 223, 13, '2026-10-21 17:00:00', '2026-10-21 17:00:00'),
(38, 26, 39, '给爸妈约的，他们说比自己下楼方便', '/imgs/notes/11/12/8b37d208-9414-4e78-b065-9199647bb3e3.jpg,/imgs/notes/11/4/fbfe0547-bd5d-454c-98c4-411e2e0dce65.jpg,/imgs/notes/11/8/ca9ba6e6-068a-4a09-8b12-5719f86d270c.jpg', '老人家腿脚不便，师傅上门带着折叠床，做完还把床单收走。爸妈现在每周都盼着。', 276, 11, '2026-10-23 22:00:00', '2026-10-23 22:00:00'),
(39, 26, 40, '刮痧之后的颜色吓到我了', '/imgs/notes/11/4/fbfe0547-bd5d-454c-98c4-411e2e0dce65.jpg,/imgs/notes/11/8/ca9ba6e6-068a-4a09-8b12-5719f86d270c.jpg', '师傅说湿气重，第二天确实轻松不少。会提前告诉你哪些部位会出痧。', 27, 9, '2026-10-28 13:00:00', '2026-10-28 13:00:00'),
(40, 27, 2, '刮痧之后的颜色吓到我了', '/imgs/notes/12/1/1afd01e5-0e16-43c2-b655-4bf733f95cfc.jpg,/imgs/notes/12/9/aab78497-ec7a-46da-820a-0ee0bbe103a3.jpg', '师傅说湿气重，第二天确实轻松不少。会提前告诉你哪些部位会出痧。', 49, 7, '2026-10-25 15:00:00', '2026-10-25 15:00:00'),
(41, 28, 5, '运动康复不是普通按摩', '/imgs/notes/13/4/1bb3d189-a34a-4809-b062-323cda7d19a9.jpg,/imgs/notes/14/13/2ec4622e-de82-4bb3-9acf-33b589850cd2.jpg,/imgs/notes/14/13/31bc9613-3637-4a36-9082-e37ce0909cbd.jpg', '先测了体态，发现我左右肩不平，给了训练动作，三次课之后跑步膝好多了。', 102, 14, '2026-10-27 20:00:00', '2026-10-27 20:00:00'),
(42, 28, 6, '足底按摩差点睡着', '/imgs/notes/14/13/2ec4622e-de82-4bb3-9acf-33b589850cd2.jpg,/imgs/notes/14/13/31bc9613-3637-4a36-9082-e37ce0909cbd.jpg,/imgs/notes/14/3/52b290eb-8b5d-403b-8373-ba0bb856d18e.jpg', '泡脚水是师傅带的药包，按到脚心的时候整个人都软了。', 133, 12, '2026-11-01 23:00:00', '2026-11-01 23:00:00'),
(43, 29, 8, '足底按摩差点睡着', '/imgs/notes/14/3/52b290eb-8b5d-403b-8373-ba0bb856d18e.jpg,/imgs/notes/15/0/b61bf453-28fc-4824-84c8-783803464c4f.jpg,/imgs/notes/15/3/fd5802b1-d4a5-4e45-badd-05cbc46c8c3d.jpg', '泡脚水是师傅带的药包，按到脚心的时候整个人都软了。', 155, 10, '2026-10-29 13:00:00', '2026-10-29 13:00:00'),
(44, 30, 11, '肩颈理疗上门，师傅手法真的绝', '/imgs/notes/15/9/cea51d9b-ac15-49f6-b9f1-9cf81e9b9c85.jpg,/imgs/notes/2/1/7b31a5da-4ee3-4c9e-a38a-2dbc8de0345a.jpg', '程序员老毛病，肩颈硬得像石头。师傅先问诊再下手法，90 分钟做完当场能转头了，比自己去店里排队省心。已经约了下周的第二次。', 208, 8, '2026-10-31 18:00:00', '2026-10-31 18:00:00'),
(45, 30, 12, '正骨那一下，我听到了咔的一声', '/imgs/notes/2/1/7b31a5da-4ee3-4c9e-a38a-2dbc8de0345a.jpg,/imgs/notes/2/2/852f49b7-432c-4d01-b7b1-8e152854f2a9.jpg,/imgs/notes/2/3/39d65be4-af94-458d-b6de-bc8ca20735bb.jpg', '有点紧张但确实舒服，做完腰不酸了。师傅说不要天天做，一周一次就够。', 239, 6, '2026-11-05 21:00:00', '2026-11-05 21:00:00'),
(46, 31, 14, '敏感肌也能做深层清洁', '/imgs/notes/2/3/39d65be4-af94-458d-b6de-bc8ca20735bb.jpg,/imgs/notes/2/4/7ed91c85-975a-40dd-9f36-abb2e87a1155.jpg,/imgs/notes/2/6/b0756279-65da-4f2d-b62a-33f74b06454a.jpg', '提前说了角质薄，美容师把清洁强度调低了，做完没有泛红。', 261, 13, '2026-11-02 23:00:00', '2026-11-02 23:00:00'),
(47, 32, 17, '头皮护理意外地舒服', '/imgs/notes/3/12/9b19dd28-1eb1-4b70-bdc2-95544eecfeb2.jpg,/imgs/notes/3/14/a6b9ec21-6708-4d6d-8f77-ed31c856e5b2.jpg,/imgs/notes/3/15/af0db3fa-5cf9-4eeb-a9fe-938de64bddc6.jpg', '一直以为自己头皮没问题，检测完发现有堆积，做完头发蓬松了不少。', 34, 11, '2026-11-04 16:00:00', '2026-11-04 16:00:00'),
(48, 32, 18, '孕期也能约的温和护理', '/imgs/notes/3/14/a6b9ec21-6708-4d6d-8f77-ed31c856e5b2.jpg,/imgs/notes/3/15/af0db3fa-5cf9-4eeb-a9fe-938de64bddc6.jpg', '只做了颈肩和头部，技师很注意姿势和力度，全程没有不适。', 65, 9, '2026-09-04 19:00:00', '2026-09-04 19:00:00'),
(49, 33, 20, '孕期也能约的温和护理', '/imgs/notes/4/0/26a7cd7e-6320-432c-a0b4-1b7418f45ec7.jpg,/imgs/notes/4/1/fa74a6d6-3026-4cb7-b0b6-35abb1e52d11.jpg', '只做了颈肩和头部，技师很注意姿势和力度，全程没有不适。', 87, 7, '2026-09-01 21:00:00', '2026-09-01 21:00:00'),
(50, 34, 23, '手法比店里细腻', '/imgs/notes/6/0/081b4b46-b2c0-47b1-8e2a-8f620d0307fb.jpg,/imgs/notes/6/8/5593ee62-04e1-410a-b6a7-4c1d50d2aee2.jpg,/imgs/notes/7/1/6f4c2442-1d3b-436f-8d49-cc704f9f0bf8.jpg', '会一直问你力度够不够，不会自顾自按。', 140, 14, '2026-09-03 14:00:00', '2026-09-03 14:00:00'),
(51, 34, 24, '带妈妈一起做，她第一次体验上门服务', '/imgs/notes/6/8/5593ee62-04e1-410a-b6a7-4c1d50d2aee2.jpg,/imgs/notes/7/1/6f4c2442-1d3b-436f-8d49-cc704f9f0bf8.jpg,/imgs/notes/7/3/2f6769c9-21de-42f8-adc0-77873273997f.jpg', '两个人两小时，比去店里排队轻松太多，妈妈现在逢人就推荐。', 171, 12, '2026-09-08 17:00:00', '2026-09-08 17:00:00'),
(52, 35, 26, '带妈妈一起做，她第一次体验上门服务', '/imgs/notes/7/3/2f6769c9-21de-42f8-adc0-77873273997f.jpg,/imgs/notes/blog1.jpg,/imgs/notes/0/0/feb2a83e-5646-46c0-a982-5e43fed31b22.jpg', '两个人两小时，比去店里排队轻松太多，妈妈现在逢人就推荐。', 193, 10, '2026-09-05 19:00:00', '2026-09-05 19:00:00'),
(53, 36, 29, '在家做SPA，比去会所放松多了', '/imgs/notes/0/5/e3e7c9e7-6654-4065-b47a-b86eb4541c33.jpg,/imgs/notes/1/12/ab329e30-b4e1-446e-993b-b00be783f142.jpg', '不用通勤、不用应付推销，做完直接躺床上睡了一觉。精油味道很淡，不冲。', 246, 8, '2026-09-07 12:00:00', '2026-09-07 12:00:00'),
(54, 36, 30, '敏感肌也能做深层清洁', '/imgs/notes/1/12/ab329e30-b4e1-446e-993b-b00be783f142.jpg,/imgs/notes/1/2/38f7e67d-7b26-41fd-bcf5-eebf71914230.jpg,/imgs/notes/1/2/4a7b496b-2a08-4af7-aa95-df2c3bd0ef97.jpg', '提前说了角质薄，美容师把清洁强度调低了，做完没有泛红。', 277, 6, '2026-09-12 15:00:00', '2026-09-12 15:00:00'),
(55, 37, 32, '给爷爷剪头发，师傅很有耐心', '/imgs/notes/1/2/4a7b496b-2a08-4af7-aa95-df2c3bd0ef97.jpg,/imgs/notes/1/2/f052df92-fc05-41a6-866e-d6da63b27645.jpg,/imgs/notes/10/7/7e97f47d-eb49-4dc9-a583-95faa7aed287.jpg', '老人坐不住，师傅一边聊一边剪，二十分钟搞定，剪得比小区门口利索。', 19, 13, '2026-09-09 17:00:00', '2026-09-09 17:00:00'),
(56, 38, 35, '烫染没翻车，颜色很正', '/imgs/notes/11/12/8b37d208-9414-4e78-b065-9199647bb3e3.jpg,/imgs/notes/11/4/fbfe0547-bd5d-454c-98c4-411e2e0dce65.jpg,/imgs/notes/11/8/ca9ba6e6-068a-4a09-8b12-5719f86d270c.jpg', '沟通了半小时色卡，最后选了冷棕色，阳光下很好看，头皮也没有刺痛。', 72, 11, '2026-09-11 22:00:00', '2026-09-11 22:00:00'),
(57, 38, 36, '小孩理发不再哭闹', '/imgs/notes/11/4/fbfe0547-bd5d-454c-98c4-411e2e0dce65.jpg,/imgs/notes/11/8/ca9ba6e6-068a-4a09-8b12-5719f86d270c.jpg', '在自己家熟悉的环境，看动画片就把头发剪了。', 103, 9, '2026-09-16 13:00:00', '2026-09-16 13:00:00'),
(58, 39, 38, '小孩理发不再哭闹', '/imgs/notes/12/1/1afd01e5-0e16-43c2-b655-4bf733f95cfc.jpg,/imgs/notes/12/9/aab78497-ec7a-46da-820a-0ee0bbe103a3.jpg', '在自己家熟悉的环境，看动画片就把头发剪了。', 125, 7, '2026-09-13 15:00:00', '2026-09-13 15:00:00'),
(59, 40, 1, '发型师会看你脸型给建议', '/imgs/notes/13/4/1bb3d189-a34a-4809-b062-323cda7d19a9.jpg,/imgs/notes/14/13/2ec4622e-de82-4bb3-9acf-33b589850cd2.jpg,/imgs/notes/14/13/31bc9613-3637-4a36-9082-e37ce0909cbd.jpg', '不是问你要剪什么，而是先看头型和发质，给的建议很中肯。', 178, 14, '2026-09-15 20:00:00', '2026-09-15 20:00:00'),
(60, 40, 2, '临时约也能约到', '/imgs/notes/14/13/2ec4622e-de82-4bb3-9acf-33b589850cd2.jpg,/imgs/notes/14/13/31bc9613-3637-4a36-9082-e37ce0909cbd.jpg,/imgs/notes/14/3/52b290eb-8b5d-403b-8373-ba0bb856d18e.jpg', '下午三点下单，五点师傅就到了，效率很高。', 209, 12, '2026-09-20 23:00:00', '2026-09-20 23:00:00'),
(61, 41, 4, '临时约也能约到', '/imgs/notes/14/3/52b290eb-8b5d-403b-8373-ba0bb856d18e.jpg,/imgs/notes/15/0/b61bf453-28fc-4824-84c8-783803464c4f.jpg,/imgs/notes/15/3/fd5802b1-d4a5-4e45-badd-05cbc46c8c3d.jpg', '下午三点下单，五点师傅就到了，效率很高。', 231, 10, '2026-09-17 13:00:00', '2026-09-17 13:00:00'),
(62, 42, 7, '在家剪头发，省了两小时通勤', '/imgs/notes/15/9/cea51d9b-ac15-49f6-b9f1-9cf81e9b9c85.jpg,/imgs/notes/2/1/7b31a5da-4ee3-4c9e-a38a-2dbc8de0345a.jpg', '总监上门带着工具箱和围布，剪完还教我怎么吹。楼下理发店剪一次也要一百多。', 284, 8, '2026-09-19 18:00:00', '2026-09-19 18:00:00'),
(63, 42, 8, '给爷爷剪头发，师傅很有耐心', '/imgs/notes/2/1/7b31a5da-4ee3-4c9e-a38a-2dbc8de0345a.jpg,/imgs/notes/2/2/852f49b7-432c-4d01-b7b1-8e152854f2a9.jpg,/imgs/notes/2/3/39d65be4-af94-458d-b6de-bc8ca20735bb.jpg', '老人坐不住，师傅一边聊一边剪，二十分钟搞定，剪得比小区门口利索。', 35, 6, '2026-09-24 21:00:00', '2026-09-24 21:00:00'),
(64, 43, 10, '美睫做完眼睛大了一圈', '/imgs/notes/2/3/39d65be4-af94-458d-b6de-bc8ca20735bb.jpg,/imgs/notes/2/4/7ed91c85-975a-40dd-9f36-abb2e87a1155.jpg,/imgs/notes/2/6/b0756279-65da-4f2d-b62a-33f74b06454a.jpg', '自然款不夸张，闭眼也没有异物感。', 57, 13, '2026-09-21 23:00:00', '2026-09-21 23:00:00'),
(65, 44, 13, '手膜之后手背的干纹淡了', '/imgs/notes/3/12/9b19dd28-1eb1-4b70-bdc2-95544eecfeb2.jpg,/imgs/notes/3/14/a6b9ec21-6708-4d6d-8f77-ed31c856e5b2.jpg,/imgs/notes/3/15/af0db3fa-5cf9-4eeb-a9fe-938de64bddc6.jpg', '冬天手特别干，做完护理再上色，效果比单做美甲好很多。', 110, 11, '2026-09-23 16:00:00', '2026-09-23 16:00:00'),
(66, 44, 14, '师傅会自带灯和吸尘器', '/imgs/notes/3/14/a6b9ec21-6708-4d6d-8f77-ed31c856e5b2.jpg,/imgs/notes/3/15/af0db3fa-5cf9-4eeb-a9fe-938de64bddc6.jpg', '完全没有粉尘，做完地上干干净净。', 141, 9, '2026-09-28 19:00:00', '2026-09-28 19:00:00'),
(67, 45, 16, '师傅会自带灯和吸尘器', '/imgs/notes/4/0/26a7cd7e-6320-432c-a0b4-1b7418f45ec7.jpg,/imgs/notes/4/1/fa74a6d6-3026-4cb7-b0b6-35abb1e52d11.jpg', '完全没有粉尘，做完地上干干净净。', 163, 7, '2026-09-25 21:00:00', '2026-09-25 21:00:00'),
(68, 46, 19, '款式可以自己带图', '/imgs/notes/6/0/081b4b46-b2c0-47b1-8e2a-8f620d0307fb.jpg,/imgs/notes/6/8/5593ee62-04e1-410a-b6a7-4c1d50d2aee2.jpg,/imgs/notes/7/1/6f4c2442-1d3b-436f-8d49-cc704f9f0bf8.jpg', '我拿了一张小红书的图，师傅照着做还原度很高。', 216, 14, '2026-09-27 14:00:00', '2026-09-27 14:00:00'),
(69, 46, 20, '周末约满，建议提前订', '/imgs/notes/6/8/5593ee62-04e1-410a-b6a7-4c1d50d2aee2.jpg,/imgs/notes/7/1/6f4c2442-1d3b-436f-8d49-cc704f9f0bf8.jpg,/imgs/notes/7/3/2f6769c9-21de-42f8-adc0-77873273997f.jpg', '约了两次才约上，热门时段要提前两天。', 247, 12, '2026-10-02 17:00:00', '2026-10-02 17:00:00'),
(70, 47, 22, '周末约满，建议提前订', '/imgs/notes/7/3/2f6769c9-21de-42f8-adc0-77873273997f.jpg,/imgs/notes/blog1.jpg,/imgs/notes/0/0/feb2a83e-5646-46c0-a982-5e43fed31b22.jpg', '约了两次才约上，热门时段要提前两天。', 269, 10, '2026-09-29 19:00:00', '2026-09-29 19:00:00'),
(71, 48, 25, '上门美甲太方便了，款式随便挑', '/imgs/notes/0/5/e3e7c9e7-6654-4065-b47a-b86eb4541c33.jpg,/imgs/notes/1/12/ab329e30-b4e1-446e-993b-b00be783f142.jpg', '在家追着剧就把指甲做了，师傅带了一整本款式册。日式手法很细，边缘处理得干干净净，一个月了还没崩边。', 42, 8, '2026-10-01 12:00:00', '2026-10-01 12:00:00'),
(72, 48, 26, '美睫做完眼睛大了一圈', '/imgs/notes/1/12/ab329e30-b4e1-446e-993b-b00be783f142.jpg,/imgs/notes/1/2/38f7e67d-7b26-41fd-bcf5-eebf71914230.jpg,/imgs/notes/1/2/4a7b496b-2a08-4af7-aa95-df2c3bd0ef97.jpg', '自然款不夸张，闭眼也没有异物感。', 73, 6, '2026-10-06 15:00:00', '2026-10-06 15:00:00'),
(73, 49, 28, '产后修复真的有用', '/imgs/notes/1/2/4a7b496b-2a08-4af7-aa95-df2c3bd0ef97.jpg,/imgs/notes/1/2/f052df92-fc05-41a6-866e-d6da63b27645.jpg,/imgs/notes/10/7/7e97f47d-eb49-4dc9-a583-95faa7aed287.jpg', '腹直肌从两指半到一指，教练很注意循序渐进，没有硬上强度。', 95, 13, '2026-10-03 17:00:00', '2026-10-03 17:00:00'),
(74, 50, 31, 'HIIT 二十分钟，比我跑一小时还累', '/imgs/notes/11/12/8b37d208-9414-4e78-b065-9199647bb3e3.jpg,/imgs/notes/11/4/fbfe0547-bd5d-454c-98c4-411e2e0dce65.jpg,/imgs/notes/11/8/ca9ba6e6-068a-4a09-8b12-5719f86d270c.jpg', '但教练会盯着心率，不会让你硬撑。', 148, 11, '2026-10-05 22:00:00', '2026-10-05 22:00:00'),
(75, 50, 32, '教练会看你家地板承重', '/imgs/notes/11/4/fbfe0547-bd5d-454c-98c4-411e2e0dce65.jpg,/imgs/notes/11/8/ca9ba6e6-068a-4a09-8b12-5719f86d270c.jpg', '很专业，先问楼板和邻居情况，跳跃动作换成低冲击版本。', 179, 9, '2026-10-10 13:00:00', '2026-10-10 13:00:00'),
(76, 51, 34, '教练会看你家地板承重', '/imgs/notes/12/1/1afd01e5-0e16-43c2-b655-4bf733f95cfc.jpg,/imgs/notes/12/9/aab78497-ec7a-46da-820a-0ee0bbe103a3.jpg', '很专业，先问楼板和邻居情况，跳跃动作换成低冲击版本。', 201, 7, '2026-10-07 15:00:00', '2026-10-07 15:00:00'),
(77, 52, 37, '饮食建议很实在', '/imgs/notes/13/4/1bb3d189-a34a-4809-b062-323cda7d19a9.jpg,/imgs/notes/14/13/2ec4622e-de82-4bb3-9acf-33b589850cd2.jpg,/imgs/notes/14/13/31bc9613-3637-4a36-9082-e37ce0909cbd.jpg', '没有让我买蛋白粉，就是调整三餐比例。', 254, 14, '2026-10-09 20:00:00', '2026-10-09 20:00:00'),
(78, 52, 38, '坚持一个月，裤子松了一圈', '/imgs/notes/14/13/2ec4622e-de82-4bb3-9acf-33b589850cd2.jpg,/imgs/notes/14/13/31bc9613-3637-4a36-9082-e37ce0909cbd.jpg,/imgs/notes/14/3/52b290eb-8b5d-403b-8373-ba0bb856d18e.jpg', '每周两次，配合走路，体重掉了四斤但围度变化更明显。', 285, 12, '2026-10-14 23:00:00', '2026-10-14 23:00:00'),
(79, 53, 40, '坚持一个月，裤子松了一圈', '/imgs/notes/14/3/52b290eb-8b5d-403b-8373-ba0bb856d18e.jpg,/imgs/notes/15/0/b61bf453-28fc-4824-84c8-783803464c4f.jpg,/imgs/notes/15/3/fd5802b1-d4a5-4e45-badd-05cbc46c8c3d.jpg', '每周两次，配合走路，体重掉了四斤但围度变化更明显。', 27, 10, '2026-10-11 13:00:00', '2026-10-11 13:00:00'),
(80, 54, 3, '私教上门，再也不用找借口不去健身房', '/imgs/notes/15/9/cea51d9b-ac15-49f6-b9f1-9cf81e9b9c85.jpg,/imgs/notes/2/1/7b31a5da-4ee3-4c9e-a38a-2dbc8de0345a.jpg', '教练自带弹力带和小哑铃，客厅两平米就能练。三次课体态明显有改善，最重要的是——没时间不再是借口了。', 80, 8, '2026-10-13 18:00:00', '2026-10-13 18:00:00'),
(81, 54, 4, '产后修复真的有用', '/imgs/notes/2/1/7b31a5da-4ee3-4c9e-a38a-2dbc8de0345a.jpg,/imgs/notes/2/2/852f49b7-432c-4d01-b7b1-8e152854f2a9.jpg,/imgs/notes/2/3/39d65be4-af94-458d-b6de-bc8ca20735bb.jpg', '腹直肌从两指半到一指，教练很注意循序渐进，没有硬上强度。', 111, 6, '2026-10-18 21:00:00', '2026-10-18 21:00:00'),
(82, 55, 6, '月嫂下户那天我哭了', '/imgs/notes/2/3/39d65be4-af94-458d-b6de-bc8ca20735bb.jpg,/imgs/notes/2/4/7ed91c85-975a-40dd-9f36-abb2e87a1155.jpg,/imgs/notes/2/6/b0756279-65da-4f2d-b62a-33f74b06454a.jpg', '26 天，产妇餐一天六顿不重样，宝宝夜里都是她起来哄。', 133, 13, '2026-10-15 23:00:00', '2026-10-15 23:00:00'),
(83, 56, 9, '临时托育解了燃眉之急', '/imgs/notes/3/12/9b19dd28-1eb1-4b70-bdc2-95544eecfeb2.jpg,/imgs/notes/3/14/a6b9ec21-6708-4d6d-8f77-ed31c856e5b2.jpg,/imgs/notes/3/15/af0db3fa-5cf9-4eeb-a9fe-938de64bddc6.jpg', '临时要出差，四个小时，阿姨带着绘本和玩具来的，孩子没哭。', 186, 11, '2026-10-17 16:00:00', '2026-10-17 16:00:00'),
(84, 56, 10, '哺乳指导一次就通了', '/imgs/notes/3/14/a6b9ec21-6708-4d6d-8f77-ed31c856e5b2.jpg,/imgs/notes/3/15/af0db3fa-5cf9-4eeb-a9fe-938de64bddc6.jpg', '之前一直堵奶，顾问调整了衔乳姿势，当天就顺畅了。', 217, 9, '2026-10-22 19:00:00', '2026-10-22 19:00:00'),
(85, 57, 12, '哺乳指导一次就通了', '/imgs/notes/4/0/26a7cd7e-6320-432c-a0b4-1b7418f45ec7.jpg,/imgs/notes/4/1/fa74a6d6-3026-4cb7-b0b6-35abb1e52d11.jpg', '之前一直堵奶，顾问调整了衔乳姿势，当天就顺畅了。', 239, 7, '2026-10-19 21:00:00', '2026-10-19 21:00:00'),
(86, 58, 15, '育婴师会每天记录喂养和睡眠', '/imgs/notes/6/0/081b4b46-b2c0-47b1-8e2a-8f620d0307fb.jpg,/imgs/notes/6/8/5593ee62-04e1-410a-b6a7-4c1d50d2aee2.jpg,/imgs/notes/7/1/6f4c2442-1d3b-436f-8d49-cc704f9f0bf8.jpg', '有个小本子，交接的时候一目了然。', 292, 14, '2026-10-21 14:00:00', '2026-10-21 14:00:00'),
(87, 58, 16, '试工一天很必要', '/imgs/notes/6/8/5593ee62-04e1-410a-b6a7-4c1d50d2aee2.jpg,/imgs/notes/7/1/6f4c2442-1d3b-436f-8d49-cc704f9f0bf8.jpg,/imgs/notes/7/3/2f6769c9-21de-42f8-adc0-77873273997f.jpg', '试工之后才知道合不合得来，平台这点做得不错。', 43, 12, '2026-10-26 17:00:00', '2026-10-26 17:00:00'),
(88, 59, 18, '试工一天很必要', '/imgs/notes/7/3/2f6769c9-21de-42f8-adc0-77873273997f.jpg,/imgs/notes/blog1.jpg,/imgs/notes/0/0/feb2a83e-5646-46c0-a982-5e43fed31b22.jpg', '试工之后才知道合不合得来，平台这点做得不错。', 65, 10, '2026-10-23 19:00:00', '2026-10-23 19:00:00'),
(89, 60, 21, '育婴师上门，我终于能睡个整觉', '/imgs/notes/0/5/e3e7c9e7-6654-4065-b47a-b86eb4541c33.jpg,/imgs/notes/1/12/ab329e30-b4e1-446e-993b-b00be783f142.jpg', '阿姨会做辅食、会拍嗝、会看大便颜色，比我这个新手妈妈专业多了。', 118, 8, '2026-10-25 12:00:00', '2026-10-25 12:00:00'),
(90, 60, 22, '月嫂下户那天我哭了', '/imgs/notes/1/12/ab329e30-b4e1-446e-993b-b00be783f142.jpg,/imgs/notes/1/2/38f7e67d-7b26-41fd-bcf5-eebf71914230.jpg,/imgs/notes/1/2/4a7b496b-2a08-4af7-aa95-df2c3bd0ef97.jpg', '26 天，产妇餐一天六顿不重样，宝宝夜里都是她起来哄。', 149, 6, '2026-10-30 15:00:00', '2026-10-30 15:00:00');
